('9c5d1efb-24f4-4602-b4b2-c91538d356bb', 'Honeybees play a critical role in global agriculture, pollinating roughly a third of the crops that humans consume, including many fruits, vegetables, and nuts. Over the past two decades, however, beekeepers around the world have reported alarming rates of colony loss, a phenomenon that scientists have linked to a combination of factors rather than any single cause. Pesticide exposure, particularly to a class of chemicals called neonicotinoids, has been shown to impair bees'' navigation and immune systems. Habitat loss has also reduced the diversity of flowering plants available to bees, limiting their access to varied nutrition. In addition, parasitic mites called Varroa destructor have spread rapidly among managed bee colonies, weakening bees and transmitting harmful viruses. In response to these threats, researchers and farmers have begun exploring solutions such as planting wildflower strips near farmland, restricting the use of certain pesticides, and breeding bees with greater resistance to mites and disease.', 3, 0.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('22890c15-1009-4cea-849a-700a8dbc711b', 'sentence_completion', 'The new bridge is expected to ___ traffic congestion significantly.', NULL, '[{"id": "d", "text": "reduce"}, {"id": "c", "text": "measure"}, {"id": "a", "text": "worsen"}, {"id": "b", "text": "ignore"}]'::jsonb, 0, '{"strategy": "new bridge...expected to = גשר חדש...צפוי. מה עושה גשר חדש לפקקים?", "correct_reason": "reduce = להפחית. גשר חדש בד''כ מפחית פקקים.", "options_analysis": ["נכון! reduce = להפחית — מטרה טבעית של גשר חדש", "measure = למדוד — לא רלוונטי לגשר", "worsen = להחמיר — הפוך ממטרת גשר חדש", "ignore = להתעלם מ- — לא רלוונטי"]}', 1.02, 0.0, 0.25, 3, 'ai', NULL, true),
('ccee9409-e113-4a45-af02-c8fdbf0def9e', 'sentence_completion', 'The company''s profits ___ after the successful product launch.', NULL, '[{"id": "a", "text": "vanished"}, {"id": "d", "text": "soared"}, {"id": "b", "text": "declined"}, {"id": "c", "text": "froze"}]'::jsonb, 1, '{"strategy": "successful product launch = השקת מוצר מוצלחת. מה קורה לרווחים אחרי הצלחה?", "correct_reason": "soared = זינקו. מוצר מצליח מזנק את הרווחים.", "options_analysis": ["vanished = נעלמו — לא הגיוני", "נכון! soared = זינקו — תוצאה טבעית של השקה מוצלחת", "declined = ירדו — הפוך מהצלחה", "froze = קפאו — לא מתאר שינוי חיובי"]}', 1.44, 0.0, 0.25, 3, 'ai', NULL, true),
('4cd13d6b-6746-4f22-9bb6-7d1e117b5cc6', 'sentence_completion', 'The manager ___ the team''s efforts despite the project''s ultimate failure.', NULL, '[{"id": "b", "text": "criticized"}, {"id": "d", "text": "punished"}, {"id": "a", "text": "praised"}, {"id": "c", "text": "ignored"}]'::jsonb, 2, '{"strategy": "despite the project''s ultimate failure = למרות כישלון הפרויקט בסופו של דבר. מה עושה מנהל טוב עם מאמץ למרות כישלון?", "correct_reason": "praised = שיבח. מנהל טוב מוקיר מאמץ גם בכישלון.", "options_analysis": ["criticized = ביקר — פחות מתאים ל''despite failure'' שמרמז על הכרה במאמץ", "punished = ענש — הפוך מהכרה במאמץ", "נכון! praised = שיבח — מתאים להכרה במאמץ למרות התוצאה", "ignored = התעלם מ- — פחות מתאים ל''despite''"]}', 1.13, 0.0, 0.25, 3, 'ai', NULL, true),
('d972dad7-647d-4b0b-8cee-6fe7d5c5e5ba', 'sentence_completion', 'The documentary ___ viewers about the dangers of plastic pollution.', NULL, '[{"id": "b", "text": "ignores"}, {"id": "d", "text": "hides"}, {"id": "c", "text": "confuses"}, {"id": "a", "text": "educates"}]'::jsonb, 3, '{"strategy": "the dangers of plastic pollution = סכנות זיהום פלסטיק. מה עושה סרט תיעודי עם סכנה?", "correct_reason": "educates = מחנך/מלמד. סרט תיעודי מלמד את הצופים.", "options_analysis": ["ignores = מתעלם מ- — לא רלוונטי", "hides = מסתיר — הפוך ממטרת תיעוד", "confuses = מבלבל — הפוך ממטרת חינוך", "נכון! educates = מלמד — פעולה טבעית של סרט תיעודי"]}', 1.03, 0.0, 0.25, 3, 'ai', NULL, true),
('21b3b470-7ba9-4247-bfa4-1087c29603d5', 'sentence_completion', 'The new employee quickly ___ herself as a valuable member of the team.', NULL, '[{"id": "b", "text": "established"}, {"id": "d", "text": "hid"}, {"id": "a", "text": "denied"}, {"id": "c", "text": "forgot"}]'::jsonb, 0, '{"strategy": "quickly...as a valuable member = במהירות...כחברה יקרת ערך. מה עשתה עובדת חדשה?", "correct_reason": "established = ביססה. עובדת חדשה מוצלחת מבססת את מעמדה.", "options_analysis": ["נכון! established = ביססה — פעולה טבעית של עובדת מצליחה", "hid = הסתירה — הפוך מלהיות חבר יקר ערך", "denied = הכחישה — לא רלוונטי", "forgot = שכחה — לא רלוונטי"]}', 0.92, 0.0, 0.25, 3, 'ai', NULL, true),
('720dd5ab-cd3c-4f9d-8bf0-3c16384026e1', 'sentence_completion', 'The court''s decision ___ years of legal debate on the matter.', NULL, '[{"id": "c", "text": "began"}, {"id": "d", "text": "ended"}, {"id": "b", "text": "ignored"}, {"id": "a", "text": "forgot"}]'::jsonb, 1, '{"strategy": "years of legal debate = שנות ויכוח משפטי. מה עושה החלטת בית משפט לוויכוח ארוך?", "correct_reason": "ended = סיימה. פסיקה סופית מסיימת ויכוח משפטי.", "options_analysis": ["began = החלה — סותר ''years of...debate'' שכבר התקיים", "נכון! ended = סיימה — פסיקה סופית מסיימת ויכוח", "ignored = התעלמה מ- — סותר את קיום ההחלטה", "forgot = שכחה — לא רלוונטי"]}', 1.01, 0.0, 0.25, 3, 'ai', NULL, true),
('da7dbb35-49b0-44de-9edb-447821d821d0', 'sentence_completion', 'The company''s aggressive pricing strategy ___ many smaller competitors out of business.', NULL, '[{"id": "b", "text": "invited"}, {"id": "d", "text": "celebrated"}, {"id": "c", "text": "drove"}, {"id": "a", "text": "kept"}]'::jsonb, 2, '{"strategy": "aggressive pricing = תמחור אגרסיבי. מה עושה תמחור אגרסיבי למתחרים קטנים?", "correct_reason": "drove = הוציאה/דחפה. תמחור אגרסיבי דוחף מתחרים קטנים מהעסק.", "options_analysis": ["invited = הזמינה — הפוך מהשפעה שלילית", "celebrated = חגגה — לא רלוונטי", "נכון! drove = דחפה — תוצאה טבעית של תמחור אגרסיבי", "kept = שמרה — הפוך מהשפעת תמחור אגרסיבי"]}', 1.19, 0.0, 0.25, 3, 'ai', NULL, true),
('73696254-9f80-4874-89ed-03b1c8ff4667', 'sentence_completion', 'The volunteers worked tirelessly to ___ the damage caused by the storm.', NULL, '[{"id": "c", "text": "cause"}, {"id": "d", "text": "ignore"}, {"id": "b", "text": "increase"}, {"id": "a", "text": "repair"}]'::jsonb, 3, '{"strategy": "damage caused by the storm = נזק שנגרם מהסערה. מה עושים מתנדבים לנזק?", "correct_reason": "repair = לתקן. מתנדבים עוזרים לתקן נזק.", "options_analysis": ["cause = לגרום — הפוך, הסערה גרמה לנזק לא המתנדבים", "ignore = להתעלם מ- — סותר ''worked tirelessly''", "increase = להגדיל — הפוך ממטרת מתנדבים", "נכון! repair = לתקן — פעולה טבעית של מתנדבים"]}', 1.03, 0.0, 0.25, 3, 'ai', NULL, true),
('0be30b5d-f7a9-49cb-839d-cec872271596', 'sentence_completion', 'The professor''s research ___ significant attention from the scientific community.', NULL, '[{"id": "b", "text": "attracted"}, {"id": "a", "text": "forgot"}, {"id": "d", "text": "denied"}, {"id": "c", "text": "avoided"}]'::jsonb, 0, '{"strategy": "significant attention = תשומת לב משמעותית. מה עושה מחקר חשוב לתשומת לב?", "correct_reason": "attracted = משכה. מחקר חשוב מושך תשומת לב.", "options_analysis": ["נכון! attracted = משכה — תוצאה טבעית של מחקר משמעותי", "forgot = שכחה — לא רלוונטי", "denied = הכחישה — לא רלוונטי", "avoided = נמנעה מ- — לא הגיוני למחקר חשוב"]}', 1.43, 0.0, 0.25, 3, 'ai', NULL, true),
('4d811ac6-1eb1-4394-be8e-eb6930258ced', 'sentence_completion', 'The city council ___ the proposal after residents expressed strong opposition.', NULL, '[{"id": "c", "text": "celebrated"}, {"id": "b", "text": "rejected"}, {"id": "a", "text": "forgot"}, {"id": "d", "text": "approved"}]'::jsonb, 1, '{"strategy": "residents expressed strong opposition = תושבים הביעו התנגדות חזקה. מה עשתה המועצה בתגובה?", "correct_reason": "rejected = דחתה. התנגדות חזקה מובילה לדחיית הצעה.", "options_analysis": ["celebrated = חגגה — לא רלוונטי", "נכון! rejected = דחתה — תגובה הגיונית להתנגדות", "forgot = שכחה — לא רלוונטי", "approved = אישרה — סותר התנגדות חזקה"]}', 1.12, 0.0, 0.25, 3, 'ai', NULL, true),
('12269f26-452d-4b5f-bb46-f51a3be0ab54', 'sentence_completion', 'The airline''s new policy ___ passengers to bring an extra bag for free.', NULL, '[{"id": "b", "text": "forbids"}, {"id": "d", "text": "ignores"}, {"id": "c", "text": "permits"}, {"id": "a", "text": "charges"}]'::jsonb, 2, '{"strategy": "for free = בחינם. מה עושה מדיניות שמאפשרת תיק נוסף חינם?", "correct_reason": "permits = מתירה. מדיניות שמאפשרת תיק נוסף מתירה זאת.", "options_analysis": ["forbids = אוסרת — הפוך מ''for free'' שמרמז על אפשרות", "ignores = מתעלמת מ- — לא רלוונטי", "נכון! permits = מתירה — תואם למדיניות מקלה", "charges = גובה תשלום — סותר ''for free''"]}', 1.59, 0.0, 0.25, 3, 'ai', NULL, true),
('a19dfcac-da7e-49ae-aa53-0f9d93fa6b4a', 'sentence_completion', 'The economist''s prediction ___ to be accurate when the recession hit as forecast.', NULL, '[{"id": "c", "text": "refused"}, {"id": "b", "text": "failed"}, {"id": "d", "text": "denied"}, {"id": "a", "text": "proved"}]'::jsonb, 3, '{"strategy": "when the recession hit as forecast = כשהמיתון פרץ כפי שנחזה. מה קרה לתחזית?", "correct_reason": "proved = התבררה. תחזית שהתגשמה כמצופה התבררה כנכונה.", "options_analysis": ["refused = סירבה — לא רלוונטי לתחזית", "failed = נכשלה — סותר את התגשמות התחזית", "denied = הכחישה — לא רלוונטי", "נכון! proved = התבררה — תוצאה של תחזית שהתגשמה"]}', 1.18, 0.0, 0.25, 3, 'ai', NULL, true),
('5cbdc457-9753-4f49-8626-d2467a10bc51', 'restatement', 'The company reported record profits despite a challenging economic climate.', NULL, '[{"id": "b", "text": "Even though the economic climate was challenging, the company reported record profits."}, {"id": "a", "text": "The economic climate was favorable, so profits were low."}, {"id": "d", "text": "The company reported record profits because of a favorable economic climate."}, {"id": "c", "text": "The company reported record losses during a challenging economic climate."}]'::jsonb, 0, '{"strategy": "despite challenging...record profits = למרות אתגר...רווחי שיא. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["נכון! אותה משמעות בדיוק: רווחי שיא למרות אתגר כלכלי", "סותר את כל המשפט המקורי", "סותר ''challenging economic climate''", "הפוך — ''losses'' סותר ''profits''"]}', 1.55, 0.0, 0.25, 3, 'ai', NULL, true),
('7e95d816-f036-47e9-a774-5ed98f3a59f7', 'restatement', 'The city''s water supply comes primarily from a reservoir located fifty miles away.', NULL, '[{"id": "c", "text": "The city has no water supply at all."}, {"id": "a", "text": "Most of the city''s water comes from a reservoir fifty miles away."}, {"id": "b", "text": "The reservoir is located within the city itself."}, {"id": "d", "text": "The city''s water supply comes from several nearby rivers."}]'::jsonb, 1, '{"strategy": "comes primarily from = מגיע בעיקר מ-. פרט מקור.", "correct_reason": "אותה משמעות בדיוק: רוב המים מגיעים ממאגר מרוחק.", "options_analysis": ["סותר את קיום אספקת המים", "נכון! אותה משמעות בדיוק: רוב המים מגיעים ממאגר מרוחק", "סותר ''fifty miles away''", "לא נאמר במקור, ואף סותר את המקור הספציפי"]}', 1.55, 0.0, 0.25, 3, 'ai', NULL, true),
('9ecf1f75-ea51-4f0f-89c8-efddd199bb1c', 'restatement', 'The new regulations apply to all businesses, regardless of their size.', NULL, '[{"id": "c", "text": "The new regulations apply only to large businesses."}, {"id": "b", "text": "The new regulations do not apply to any businesses."}, {"id": "d", "text": "The new regulations apply to every business, no matter how big or small."}, {"id": "a", "text": "Small businesses are exempt from the new regulations."}]'::jsonb, 2, '{"strategy": "apply to all...regardless of size = חלות על כולם...ללא קשר לגודל.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר ''all businesses, regardless of their size''", "סותר לגמרי — התקנות כן חלות", "נכון! אותה משמעות בדיוק: חלות על כל עסק בלי קשר לגודל", "סותר ''apply to all businesses''"]}', 1.38, 0.0, 0.25, 3, 'ai', NULL, true),
('e8cf06a8-daff-4b69-a2cb-d93162759a1d', 'restatement', 'The museum''s most popular exhibit draws thousands of visitors each week.', NULL, '[{"id": "d", "text": "The exhibit was popular only once, many years ago."}, {"id": "a", "text": "The museum has no popular exhibits."}, {"id": "b", "text": "The museum''s most popular exhibit attracts almost no visitors."}, {"id": "c", "text": "Thousands of visitors come to see the museum''s most popular exhibit every week."}]'::jsonb, 3, '{"strategy": "draws thousands each week = מושך אלפים כל שבוע.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר ''each week'' — זה קורה באופן שוטף, לא חד פעמי", "סותר ''most popular exhibit''", "הפוך — ''almost no visitors'' סותר ''thousands''", "נכון! אותה משמעות בדיוק: אלפי מבקרים כל שבוע"]}', 1.0, 0.0, 0.25, 3, 'ai', NULL, true),
('58457034-be9f-4e7b-97c5-da5d4308c71a', 'restatement', 'The report highlights several areas where the company could improve its efficiency.', NULL, '[{"id": "c", "text": "The report identifies multiple areas for potential efficiency improvements."}, {"id": "d", "text": "The report has nothing to say about the company''s efficiency."}, {"id": "a", "text": "The report claims the company is already perfectly efficient."}, {"id": "b", "text": "The report criticizes the company for having no room to improve."}]'::jsonb, 0, '{"strategy": "highlights several areas...could improve = מדגיש כמה תחומים...יכולה להשתפר.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: כמה תחומים לשיפור פוטנציאלי ביעילות", "סותר את כל התוכן של הדוח", "סותר ''could improve its efficiency''", "סותר לגמרי — הדוח כן מציין תחומים לשיפור"]}', 1.19, 0.0, 0.25, 3, 'ai', NULL, true),
('21e93d86-c7bc-4bdd-8452-112ed1690fca', 'restatement', 'The negotiations broke down after both sides refused to make further concessions.', NULL, '[{"id": "b", "text": "The negotiations succeeded because both sides made concessions."}, {"id": "c", "text": "Because neither side would make further concessions, the negotiations broke down."}, {"id": "a", "text": "The negotiations broke down before they even began."}, {"id": "d", "text": "Both sides happily agreed to compromise."}]'::jsonb, 1, '{"strategy": "broke down after refused = קרסו אחרי סירוב. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["הפוך — ''succeeded'' סותר ''broke down''", "נכון! אותה סיבה-תוצאה בדיוק", "סותר את סדר האירועים — המו''מ כן התחיל", "סותר ''refused to make further concessions''"]}', 1.21, 0.0, 0.25, 3, 'ai', NULL, true),
('82df65bb-ef95-4f79-9803-ad974f47619e', 'restatement', 'The company''s stock has fluctuated wildly since the merger was announced.', NULL, '[{"id": "d", "text": "No one noticed any change in the stock price."}, {"id": "b", "text": "The stock price was announced before the merger."}, {"id": "a", "text": "Since the merger was announced, the company''s stock has changed unpredictably."}, {"id": "c", "text": "The company''s stock has remained perfectly stable since the merger."}]'::jsonb, 2, '{"strategy": "fluctuated wildly since = תנודתי מאוד מאז. תיאור.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר ''fluctuated wildly''", "לא נאמר במקור — המשפט מדבר על המניה, לא המיזוג", "נכון! אותה משמעות בדיוק: שינויים בלתי צפויים מאז המיזוג", "הפוך — ''stable'' סותר ''fluctuated wildly''"]}', 1.09, 0.0, 0.25, 3, 'ai', NULL, true),
('4d410ef5-30c7-4c76-ac14-6335c3650f7d', 'restatement', 'The new curriculum places greater emphasis on practical skills than the old one did.', NULL, '[{"id": "b", "text": "The new curriculum focuses less on practical skills than the old curriculum."}, {"id": "d", "text": "The new curriculum ignores practical skills entirely."}, {"id": "c", "text": "The old and new curricula are identical in every way."}, {"id": "a", "text": "Compared to the old curriculum, the new one emphasizes practical skills more."}]'::jsonb, 3, '{"strategy": "greater emphasis than old = דגש רב יותר מהישן. השוואה.", "correct_reason": "אותה השוואה בדיוק.", "options_analysis": ["הפוך — ''less'' סותר ''greater emphasis''", "סותר ''greater emphasis on practical skills''", "סותר את ההשוואה שבמקור — יש הבדל ביניהם", "נכון! אותה השוואה בדיוק: דגש רב יותר בהשוואה לישן"]}', 1.58, 0.0, 0.25, 3, 'ai', NULL, true),
('3bbc2dbb-9f15-4b24-bd79-a8ca4e10e2c9', 'restatement', 'The team''s victory was largely attributed to their new coach''s strategy.', NULL, '[{"id": "c", "text": "The new coach''s strategy was largely responsible for the team''s victory."}, {"id": "d", "text": "The team''s victory had nothing to do with the coach."}, {"id": "b", "text": "The team lost due to their new coach''s strategy."}, {"id": "a", "text": "The old coach was responsible for the recent victory."}]'::jsonb, 0, '{"strategy": "attributed to = יוחס ל-. סיבה עיקרית.", "correct_reason": "אותה משמעות בדיוק: האסטרטגיה הייתה הסיבה העיקרית.", "options_analysis": ["נכון! אותה משמעות בדיוק: האסטרטגיה הייתה הסיבה העיקרית לניצחון", "סותר ''attributed to their new coach''s strategy''", "הפוך — ''lost'' סותר ''victory''", "סותר ''new coach'' — זה היה המאמן החדש, לא הישן"]}', 1.55, 0.0, 0.25, 3, 'ai', NULL, true),
('fda5c50c-5865-4130-8a54-986c57b67cb6', 'restatement', 'The company''s revenue grew steadily throughout the year, with no major setbacks.', NULL, '[{"id": "a", "text": "The company''s revenue declined steadily throughout the year."}, {"id": "b", "text": "The company''s revenue increased consistently all year without significant problems."}, {"id": "c", "text": "The company had no revenue at any point during the year."}, {"id": "d", "text": "The company faced major setbacks that halted all revenue growth."}]'::jsonb, 1, '{"strategy": "grew steadily...no major setbacks = גדלה בהתמדה...בלי תקלות גדולות.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — ''declined'' סותר ''grew''", "נכון! אותה משמעות בדיוק: גדילה עקבית לאורך השנה ללא בעיות משמעותיות", "סותר לגמרי — הייתה הכנסה שגדלה", "סותר ''no major setbacks''"]}', 1.23, 0.0, 0.25, 3, 'ai', NULL, true),
('32387831-dcd1-4ea5-93dd-fcc2ea557c73', 'restatement', 'The scientist''s groundbreaking discovery challenged long-held assumptions in the field.', NULL, '[{"id": "b", "text": "No assumptions existed in the field before the discovery."}, {"id": "c", "text": "The discovery was quickly dismissed as unimportant."}, {"id": "a", "text": "The discovery called into question ideas that had been accepted for a long time."}, {"id": "d", "text": "The discovery confirmed everything scientists already believed."}]'::jsonb, 2, '{"strategy": "challenged long-held assumptions = אתגרה הנחות ותיקות. השפעה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר ''long-held assumptions'' — הן כן היו קיימות", "סותר ''groundbreaking'' — תגלית פורצת דרך לא נדחית כלא חשובה", "נכון! אותה משמעות בדיוק: הטילה ספק בהנחות ותיקות", "הפוך — ''confirmed'' סותר ''challenged''"]}', 1.05, 0.0, 0.25, 3, 'ai', NULL, true),
('1f047731-ec7e-4833-ad5d-5b90fb5e8ab5', 'restatement', 'The restaurant''s new menu features dishes inspired by cuisines from around the world.', NULL, '[{"id": "b", "text": "The new menu has not changed at all."}, {"id": "c", "text": "The restaurant removed all international dishes from its menu."}, {"id": "d", "text": "The restaurant''s menu includes only one type of local cuisine."}, {"id": "a", "text": "The new menu offers dishes influenced by international cuisines."}]'::jsonb, 3, '{"strategy": "features dishes inspired by cuisines from around the world = כולל מנות בהשראת מטבחים מהעולם.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר ''new menu'' — המשפט מתאר תפריט חדש", "הפוך — ''removed'' סותר ''features''", "סותר ''cuisines from around the world'' — יש גיוון בין-לאומי", "נכון! אותה משמעות בדיוק: מנות בהשראה בין-לאומית"]}', 1.13, 0.0, 0.25, 3, 'ai', NULL, true),
('126ad444-91e2-4025-ae80-f084e50736e0', 'reading_comprehension', 'What is the passage mainly about?', '9c5d1efb-24f4-4602-b4b2-c91538d356bb', '[{"id": "a", "text": "The causes of declining bee populations and possible solutions"}, {"id": "c", "text": "Why fruits and vegetables are healthy to eat"}, {"id": "b", "text": "The history of beekeeping as a profession"}, {"id": "d", "text": "How honey is produced by bees"}]'::jsonb, 0, '{"strategy": "שאלת רעיון מרכזי — הפסקה עוסקת בסיבות לירידה באוכלוסיית הדבורים ובפתרונות אפשריים.", "correct_reason": "כל הפסקה סוקרת את הגורמים לירידה באוכלוסיית הדבורים ואת המאמצים להתמודד עמה.", "options_analysis": ["נכון! הגורמים לירידה בדבורים והפתרונות = הנושא הכולל", "לא הנושא, רק אזכור רקע", "לא מוזכר בפסקה", "לא מוזכר בפסקה כלל"]}', 0.98, 0.0, 0.25, 3, 'ai', NULL, true),
('505c4b08-7bed-4995-bee7-b6831d829ae7', 'reading_comprehension', 'According to the passage, what percentage of crops do honeybees help pollinate?', '9c5d1efb-24f4-4602-b4b2-c91538d356bb', '[{"id": "d", "text": "Almost all of them"}, {"id": "c", "text": "Roughly a third"}, {"id": "a", "text": "Exactly half"}, {"id": "b", "text": "Less than five percent"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את האחוז המוזכר בפסקה.", "correct_reason": "הפסקה אומרת: ''pollinating roughly a third of the crops that humans consume''.", "options_analysis": ["לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה"]}', 1.37, 0.0, 0.25, 3, 'ai', NULL, true),
('1f737fe9-dc34-4cd7-8b9a-83d1573f0b1c', 'reading_comprehension', 'The word "impair" in the passage most closely means:', '9c5d1efb-24f4-4602-b4b2-c91538d356bb', '[{"id": "c", "text": "to improve significantly"}, {"id": "b", "text": "to strengthen"}, {"id": "a", "text": "to damage or weaken"}, {"id": "d", "text": "to completely destroy"}]'::jsonb, 2, '{"strategy": "אוצר מילים בהקשר — ''impair bees'' navigation and immune systems''.", "correct_reason": "impair = לפגוע/להחליש.", "options_analysis": ["הפוך גמור למשמעות המילה", "הפוך גמור למשמעות המילה", "נכון! impair = לפגוע/להחליש", "לא מדויק — ''impair'' הוא פגיעה חלקית, לא הרס מוחלט"]}', 1.42, 0.0, 0.25, 3, 'ai', NULL, true),
('05e814d8-1179-4b46-b072-eecb56eab6da', 'reading_comprehension', 'According to the passage, what has habitat loss done to bees?', '9c5d1efb-24f4-4602-b4b2-c91538d356bb', '[{"id": "c", "text": "Completely eliminated all bee colonies"}, {"id": "a", "text": "Had no effect on bee nutrition"}, {"id": "d", "text": "Given them access to more flowering plants"}, {"id": "b", "text": "Reduced the diversity of flowering plants available to them"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את השפעת אובדן בית הגידול בפסקה.", "correct_reason": "הפסקה אומרת: ''Habitat loss has also reduced the diversity of flowering plants available to bees''.", "options_analysis": ["לא נאמר בפסקה, וגם לא מדויק", "סותר את הפסקה — יש השפעה על תזונה", "הפוך גמור למה שנאמר בפסקה", "נכון! נאמר במפורש בפסקה"]}', 1.3, 0.0, 0.25, 3, 'ai', NULL, true),
('139a9458-fc4e-41cf-bc81-5fa54a00096e', 'reading_comprehension', 'What solutions are researchers and farmers exploring, according to the passage?', '9c5d1efb-24f4-4602-b4b2-c91538d356bb', '[{"id": "d", "text": "Planting wildflower strips, restricting certain pesticides, and breeding resistant bees"}, {"id": "b", "text": "Increasing the use of neonicotinoid pesticides"}, {"id": "c", "text": "Banning all agriculture near beehives"}, {"id": "a", "text": "Replacing bees entirely with robotic pollinators"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את הפתרונות המוצעים בסוף הפסקה.", "correct_reason": "הפסקה אומרת: ''exploring solutions such as planting wildflower strips near farmland, restricting the use of certain pesticides, and breeding bees with greater resistance''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "הפוך — הפסקה מציעה הגבלה, לא הגברה של קוטלי חרקים", "לא נאמר בפסקה", "לא נאמר בפסקה"]}', 1.44, 0.0, 0.25, 3, 'ai', NULL, true);